        }
        party.1.observe(&declaration);
        let mut funders = BTreeMap::new();
        for entry in &declaration.entries {
            if let Some(funder) = entry
                .funder
                .as_ref()
                .and_then(|reference| source.funders.get(&reference.id.value()))
